/**
 * Storage abstraction: the same interface backs local disk (development,
 * no credentials) and AWS S3 (production). Media reads are served through
 * short-lived signed URLs generated by this layer.
 */
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { createReadStream, type ReadStream } from 'node:fs';
import { env } from '../config/env';
import { logger } from '../lib/logger';

export interface StorageObject {
  key: string;
  contentType?: string;
  cacheControl?: string;
}

export interface StorageDriver {
  readonly kind: 'local' | 's3';
  put(key: string, body: Buffer | ReadStream, opts?: { contentType?: string }): Promise<void>;
  get(key: string): Promise<Buffer>;
  exists(key: string): Promise<boolean>;
  delete(key: string): Promise<void>;
  deletePrefix(prefix: string): Promise<void>;
  list(prefix: string): Promise<string[]>;
  /** Absolute filesystem path when the driver has one (local dev transcode). */
  localPath(key: string): string | null;
  /** Public/CDN absolute URL for a key (used by players after playback auth). */
  publicUrl(key: string): string;
}

/* ------------------------------------------------------------------ *
 * Local driver
 * ------------------------------------------------------------------ */
class LocalDriver implements StorageDriver {
  readonly kind = 'local' as const;
  private readonly root: string;

  constructor(root: string) {
    this.root = path.resolve(root);
    fs.mkdirSync(this.root, { recursive: true });
  }

  private resolve(key: string): string {
    const abs = path.resolve(this.root, key);
    if (!abs.startsWith(this.root)) throw new Error(`Invalid storage key: ${key}`);
    return abs;
  }

  async put(key: string, body: Buffer | ReadStream): Promise<void> {
    const target = this.resolve(key);
    await fsp.mkdir(path.dirname(target), { recursive: true });
    if (Buffer.isBuffer(body)) {
      await fsp.writeFile(target, body);
      return;
    }
    await new Promise<void>((resolve, reject) => {
      const out = fs.createWriteStream(target);
      body.pipe(out);
      out.on('finish', () => resolve());
      out.on('error', reject);
      body.on('error', reject);
    });
  }

  async get(key: string): Promise<Buffer> {
    return fsp.readFile(this.resolve(key));
  }

  async exists(key: string): Promise<boolean> {
    try {
      await fsp.access(this.resolve(key));
      return true;
    } catch {
      return false;
    }
  }

  async delete(key: string): Promise<void> {
    await fsp.rm(this.resolve(key), { force: true });
  }

  async deletePrefix(prefix: string): Promise<void> {
    await fsp.rm(this.resolve(prefix), { recursive: true, force: true });
  }

  async list(prefix: string): Promise<string[]> {
    const base = this.resolve(prefix);
    const results: string[] = [];
    const walk = async (dir: string, rel: string): Promise<void> => {
      let entries: fs.Dirent[];
      try {
        entries = await fsp.readdir(dir, { withFileTypes: true });
      } catch {
        return;
      }
      for (const e of entries) {
        const relPath = rel ? `${rel}/${e.name}` : e.name;
        if (e.isDirectory()) await walk(path.join(dir, e.name), relPath);
        else results.push(`${prefix}/${relPath}`.replace(/\/+/g, '/'));
      }
    };
    await walk(base, '');
    return results;
  }

  localPath(key: string): string | null {
    return this.resolve(key);
  }

  publicUrl(key: string): string {
    if (env.PUBLIC_MEDIA_BASE_URL) {
      return `${env.PUBLIC_MEDIA_BASE_URL.replace(/\/$/, '')}/${key}`;
    }
    return `${env.APP_URL.replace(/\/$/, '')}/media/${key}`;
  }
}

/* ------------------------------------------------------------------ *
 * S3 driver (lazy — only instantiated when configured)
 * ------------------------------------------------------------------ */
class S3Driver implements StorageDriver {
  readonly kind = 's3' as const;
  private client: import('@aws-sdk/client-s3').S3Client | null = null;
  private readonly bucket: string;

  constructor(bucket: string) {
    this.bucket = bucket;
  }

  private async ensure() {
    if (!this.client) {
      const { S3Client } = await import('@aws-sdk/client-s3');
      this.client = new S3Client({
        region: env.S3_REGION,
        ...(env.S3_ENDPOINT ? { endpoint: env.S3_ENDPOINT, forcePathStyle: true } : {}),
      });
    }
    return this.client;
  }

  async put(key: string, body: Buffer | ReadStream, opts?: { contentType?: string }): Promise<void> {
    const client = await this.ensure();
    const { PutObjectCommand } = await import('@aws-sdk/client-s3');
    const bytes = Buffer.isBuffer(body) ? body : await streamToBuffer(body);
    await client.send(
      new PutObjectCommand({
        Bucket: this.bucket,
        Key: key,
        Body: bytes,
        ...(opts?.contentType ? { ContentType: opts.contentType } : {}),
      }),
    );
  }

  async get(key: string): Promise<Buffer> {
    const client = await this.ensure();
    const { GetObjectCommand } = await import('@aws-sdk/client-s3');
    const res = await client.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
    if (!res.Body) throw new Error(`Empty object: ${key}`);
    return streamToBuffer(res.Body as unknown as ReadStream);
  }

  async exists(key: string): Promise<boolean> {
    try {
      await this.get(key);
      return true;
    } catch {
      return false;
    }
  }

  async delete(key: string): Promise<void> {
    const client = await this.ensure();
    const { DeleteObjectCommand } = await import('@aws-sdk/client-s3');
    await client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key }));
  }

  async deletePrefix(prefix: string): Promise<void> {
    const keys = await this.list(prefix);
    await Promise.all(keys.map((k) => this.delete(k)));
  }

  async list(prefix: string): Promise<string[]> {
    const client = await this.ensure();
    const { ListObjectsV2Command } = await import('@aws-sdk/client-s3');
    const keys: string[] = [];
    let token: string | undefined;
    do {
      const res = await client.send(
        new ListObjectsV2Command({ Bucket: this.bucket, Prefix: prefix, ContinuationToken: token }),
      );
      for (const obj of res.Contents ?? []) if (obj.Key) keys.push(obj.Key);
      token = res.IsTruncated ? res.NextContinuationToken : undefined;
    } while (token);
    return keys;
  }

  localPath(): string | null {
    return null;
  }

  publicUrl(key: string): string {
    if (env.CDN_BASE_URL) return `${env.CDN_BASE_URL.replace(/\/$/, '')}/${key}`;
    if (env.PUBLIC_MEDIA_BASE_URL) return `${env.PUBLIC_MEDIA_BASE_URL.replace(/\/$/, '')}/${key}`;
    return `https://${this.bucket}.s3.${env.S3_REGION}.amazonaws.com/${key}`;
  }
}

async function streamToBuffer(stream: ReadStream): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of stream) chunks.push(Buffer.from(chunk));
  return Buffer.concat(chunks);
}

let driver: StorageDriver | null = null;

export function storage(): StorageDriver {
  if (!driver) {
    if (env.STORAGE_DRIVER === 's3' && env.S3_BUCKET) {
      driver = new S3Driver(env.S3_BUCKET);
      logger.info({ bucket: env.S3_BUCKET }, 'Storage driver: s3');
    } else {
      driver = new LocalDriver(env.LOCAL_STORAGE_DIR);
      logger.info({ dir: env.LOCAL_STORAGE_DIR }, 'Storage driver: local');
    }
  }
  return driver;
}

export function setStorageDriver(next: StorageDriver): void {
  driver = next;
}

/* ------------------------------------------------------------------ *
 * Key helpers — deterministic, tenant-safe key layout
 * ------------------------------------------------------------------ */
export const keys = {
  sourceVideo: (courseId: string, lessonId: string, assetId: string, ext: string) =>
    `courses/${courseId}/lessons/${lessonId}/source/${assetId}.${ext.replace(/^\./, '')}`,
  hlsPrefix: (courseId: string, lessonId: string, assetId: string) =>
    `courses/${courseId}/lessons/${lessonId}/hls/${assetId}`,
  lessonResource: (courseId: string, lessonId: string, fileName: string) =>
    `courses/${courseId}/lessons/${lessonId}/resources/${Date.now()}-${sanitize(fileName)}`,
  thumbnail: (courseId: string, fileName: string) =>
    `courses/${courseId}/thumbnails/${Date.now()}-${sanitize(fileName)}`,
  certificate: (certificateNumber: string) => `certificates/${certificateNumber}.pdf`,
};

function sanitize(name: string): string {
  return name.replace(/[^a-zA-Z0-9._-]/g, '_').slice(0, 120);
}
